-- P010 · Schema 1 — profiles, user_settings, consents, body_measurements
-- See docs/02-MIMARI.md §3.1.
--
-- Conventions for every synced user table:
--   id          uuid, generated by the client
--   user_id     uuid -> auth.users, cascades on account deletion
--   created_at / updated_at (server clock, maintained by set_updated_at) / deleted_at (soft delete)
--   index on (user_id, updated_at) for the sync pull cursor
--   RLS: the owner may select / insert / update; there is no delete policy (soft delete only).

------------------------------------------------------------------------------
-- Shared trigger function
------------------------------------------------------------------------------
-- The sync cursor is server time, so the client can never set updated_at.
create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

------------------------------------------------------------------------------
-- profiles (one row per user)
------------------------------------------------------------------------------
create table public.profiles (
  id                uuid primary key,
  user_id           uuid not null unique references auth.users (id) on delete cascade,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  deleted_at        timestamptz,

  first_name        text,
  last_name         text,
  birth_date        date not null,
  sex               text not null default 'unspecified',
  height_cm         numeric(5, 1) not null,
  unit_system       text not null default 'metric',
  experience        text not null,
  goal              text not null,
  weekly_frequency  smallint not null,
  equipment_access  text not null,
  limitations       text[] not null default '{}',
  locale            text not null default 'en',

  constraint profiles_sex_check
    check (sex in ('male', 'female', 'unspecified')),
  constraint profiles_height_check
    check (height_cm between 100 and 250),
  -- Minimum age 16. Rows only get older, so the check stays true over time.
  constraint profiles_min_age_check
    check (birth_date <= (current_date - interval '16 years')::date),
  constraint profiles_unit_system_check
    check (unit_system in ('metric', 'imperial')),
  constraint profiles_experience_check
    check (experience in ('none', 'under_6_months', 'six_months_to_2_years', 'two_to_5_years', 'over_5_years')),
  constraint profiles_goal_check
    check (goal in ('strength', 'muscle_gain', 'fat_loss', 'general_health')),
  constraint profiles_weekly_frequency_check
    check (weekly_frequency between 1 and 7),
  constraint profiles_equipment_access_check
    check (equipment_access in ('full_gym', 'home_barbell', 'home_dumbbell', 'bodyweight_only'))
);

create index profiles_user_id_updated_at_idx on public.profiles (user_id, updated_at);

create trigger profiles_set_updated_at
  before insert or update on public.profiles
  for each row execute function public.set_updated_at();

------------------------------------------------------------------------------
-- user_settings (one row per user)
------------------------------------------------------------------------------
create table public.user_settings (
  id                    uuid primary key,
  user_id               uuid not null unique references auth.users (id) on delete cascade,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  deleted_at            timestamptz,

  theme                 text not null default 'system',
  weight_unit           text not null default 'kg',
  length_unit           text not null default 'cm',
  reference_group       text not null default 'gym',
  rir_enabled           boolean not null default true,
  rest_timer_seconds    smallint not null default 120,
  default_bar_kg        numeric(5, 2) not null default 20,
  -- Plates are stored in kg like every other weight.
  available_plates_kg   numeric(5, 2)[] not null default '{1.25,2.5,5,10,15,20,25}',

  constraint user_settings_theme_check
    check (theme in ('system', 'dark', 'light')),
  constraint user_settings_weight_unit_check
    check (weight_unit in ('kg', 'lb')),
  constraint user_settings_length_unit_check
    check (length_unit in ('cm', 'in')),
  constraint user_settings_reference_group_check
    check (reference_group in ('gym', 'general')),
  constraint user_settings_rest_timer_check
    check (rest_timer_seconds between 0 and 1800),
  constraint user_settings_default_bar_check
    check (default_bar_kg between 0 and 50)
);

create index user_settings_user_id_updated_at_idx on public.user_settings (user_id, updated_at);

create trigger user_settings_set_updated_at
  before insert or update on public.user_settings
  for each row execute function public.set_updated_at();

------------------------------------------------------------------------------
-- consents (append-only; the current state is the latest row per kind)
------------------------------------------------------------------------------
create table public.consents (
  id          uuid primary key,
  user_id     uuid not null references auth.users (id) on delete cascade,
  created_at  timestamptz not null default now(),
  -- Kept for the uniform sync cursor; rows are never updated (no update policy).
  updated_at  timestamptz not null default now(),

  kind        text not null,
  version     text not null,
  granted     boolean not null,

  constraint consents_kind_check
    check (kind in ('terms', 'privacy', 'ai_sharing', 'ml_contribution'))
);

create index consents_user_id_updated_at_idx on public.consents (user_id, updated_at);
create index consents_user_id_kind_created_at_idx on public.consents (user_id, kind, created_at desc);

create trigger consents_set_updated_at
  before insert or update on public.consents
  for each row execute function public.set_updated_at();

------------------------------------------------------------------------------
-- body_measurements
------------------------------------------------------------------------------
create table public.body_measurements (
  id            uuid primary key,
  user_id       uuid not null references auth.users (id) on delete cascade,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  deleted_at    timestamptz,

  date          date not null,
  weight_kg     numeric(5, 2) not null,
  body_fat_pct  numeric(4, 1),
  source        text not null default 'manual',

  constraint body_measurements_weight_check
    check (weight_kg between 20 and 400),
  constraint body_measurements_body_fat_check
    check (body_fat_pct is null or body_fat_pct between 2 and 70),
  constraint body_measurements_source_check
    check (source in ('manual', 'healthkit', 'import'))
);

create index body_measurements_user_id_updated_at_idx on public.body_measurements (user_id, updated_at);
create index body_measurements_user_id_date_idx on public.body_measurements (user_id, date desc);

create trigger body_measurements_set_updated_at
  before insert or update on public.body_measurements
  for each row execute function public.set_updated_at();

------------------------------------------------------------------------------
-- Row level security: owner may select / insert / update; nobody may delete.
-- consents is insert + select only.
------------------------------------------------------------------------------
alter table public.profiles          enable row level security;
alter table public.user_settings     enable row level security;
alter table public.consents          enable row level security;
alter table public.body_measurements enable row level security;

-- Tables are only reachable by signed-in users; anon gets nothing, and no role may delete.
revoke all on public.profiles, public.user_settings, public.consents, public.body_measurements
  from anon, authenticated;
grant select, insert, update on public.profiles, public.user_settings, public.body_measurements
  to authenticated;
grant select, insert on public.consents to authenticated;

create policy profiles_select_own on public.profiles
  for select to authenticated using (user_id = (select auth.uid()));
create policy profiles_insert_own on public.profiles
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy profiles_update_own on public.profiles
  for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

create policy user_settings_select_own on public.user_settings
  for select to authenticated using (user_id = (select auth.uid()));
create policy user_settings_insert_own on public.user_settings
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy user_settings_update_own on public.user_settings
  for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

create policy consents_select_own on public.consents
  for select to authenticated using (user_id = (select auth.uid()));
create policy consents_insert_own on public.consents
  for insert to authenticated with check (user_id = (select auth.uid()));

create policy body_measurements_select_own on public.body_measurements
  for select to authenticated using (user_id = (select auth.uid()));
create policy body_measurements_insert_own on public.body_measurements
  for insert to authenticated with check (user_id = (select auth.uid()));
create policy body_measurements_update_own on public.body_measurements
  for update to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
